(6222886, 918871, 96751, '<td valign="top">Terrific portrait.  The eyes are really terrific.</td>', 'Terrific portrait.  The eyes are really terrific.', '2010-11-15 01:22:51.000000', NULL, 1),
(6222889, 920095, 96751, '<td valign="top">Very well done.  Really great tonal range.</td>', 'Very well done.  Really great tonal range.', '2010-11-15 01:25:41.000000', NULL, 1),
(6222890, 919949, 96751, '<td valign="top">How weird!!!!  Great find.</td>', 'How weird!!!!  Great find.', '2010-11-15 01:26:13.000000', NULL, 1),
(6222893, 919839, 96751, '<td valign="top">You are, without a doubt, the most passionate photographer I have ever seen.  Your photography is excellent, but so is your art direction, lighting.  I''d give anything to be inside your mind for just an hour :-)</td>', 'You are, without a doubt, the most passionate photographer I have ever seen.  Your photography is excellent, but so is your art direction, lighting.  I''d give anything to be inside your mind for just an hour :-)', '2010-11-15 01:28:53.000000', NULL, 1),
(6222894, 920020, 96751, '<td valign="top">Fabulously processed.</td>', 'Fabulously processed.', '2010-11-15 01:29:15.000000', NULL, 1),
(6222895, 919430, 96751, '<td valign="top">This is just so sad and beautiful.  The colors are just so marvelous and soft.</td>', 'This is just so sad and beautiful.  The colors are just so marvelous and soft.', '2010-11-15 01:30:15.000000', NULL, 1),
(6222897, 920062, 96751, '<td valign="top">Oh, I want to pay too!!  Beautiful image, crisp and detailed, although the eyes look a little unreal.</td>', 'Oh, I want to pay too!!  Beautiful image, crisp and detailed, although the eyes look a little unreal.', '2010-11-15 01:31:29.000000', NULL, 1),
(6222899, 919840, 96751, '<td valign="top">Delicate and eloquent.  I love the implied pooch.</td>', 'Delicate and eloquent.  I love the implied pooch.', '2010-11-15 01:32:02.000000', NULL, 1),
(6222900, 920036, 96751, '<td valign="top">Beautiful.</td>', 'Beautiful.', '2010-11-15 01:32:10.000000', NULL, 1),
(6222901, 919916, 96751, '<td valign="top">My cat used to LOVE those toys.  If I went anywhere near it he''d go bananas.  This is a strange and somewhat surreal image, like a Twilight Zone episode.</td>', 'My cat used to LOVE those toys.  If I went anywhere near it he''d go bananas.  This is a strange and somewhat surreal image, like a Twilight Zone episode.', '2010-11-15 01:33:06.000000', NULL, 1),
(6222902, 919789, 96751, '<td valign="top">Hehehe.  They can sleep anywhere, in any position :-)</td>', 'Hehehe.  They can sleep anywhere, in any position :-)', '2010-11-15 01:33:29.000000', NULL, 1),
(6222903, 919616, 96751, '<td valign="top">I love this museum.  The restaurant on the mezzanine is really lovely, too.</td>', 'I love this museum.  The restaurant on the mezzanine is really lovely, too.', '2010-11-15 01:34:01.000000', NULL, 1),
(6222904, 919792, 96751, '<td valign="top">Fabulous bokeh on the lights.</td>', 'Fabulous bokeh on the lights.', '2010-11-15 01:34:27.000000', NULL, 1),
(6222907, 919749, 96751, '<td valign="top">The square crop is PERFECT for this.</td>', 'The square crop is PERFECT for this.', '2010-11-15 01:34:51.000000', NULL, 1),
(6222909, 920096, 96751, '<td valign="top">Awesome capture.  Incredible detail and tones.</td>', 'Awesome capture.  Incredible detail and tones.', '2010-11-15 01:35:27.000000', NULL, 1),
(6222911, 920021, 4162, '<td valign="top">This is beautiful, the colours are gorgeous 9</td>', 'This is beautiful, the colours are gorgeous 9', '2010-11-15 01:35:42.000000', NULL, 1),
(6222912, 919999, 96751, '<td valign="top">Oh, if only this were lit better.  What a great subject.</td>', 'Oh, if only this were lit better.  What a great subject.', '2010-11-15 01:36:01.000000', NULL, 1),
(6222913, 919732, 96751, '<td valign="top">LOL!  Those pink boots and the uneven socks are KILLER.  And the bands of texture are fabulous.  I love this image.</td>', 'LOL!  Those pink boots and the uneven socks are KILLER.  And the bands of texture are fabulous.  I love this image.', '2010-11-15 01:36:29.000000', NULL, 1),
(6222914, 919938, 96751, '<td valign="top">Sweet.</td>', 'Sweet.', '2010-11-15 01:36:38.000000', NULL, 1),
(6222915, 919917, 4162, '<td valign="top">what a lovely capture, really like the monochrome.</td>', 'what a lovely capture, really like the monochrome.', '2010-11-15 01:36:39.000000', NULL, 1),
(6222916, 919889, 96751, '<td valign="top">This is so beautiful, Deb.  The tree is so delicate and Oriental-art-looking.  There is something really moving and tender about this image.</td>', 'This is so beautiful, Deb.  The tree is so delicate and Oriental-art-looking.  There is something really moving and tender about this image.', '2010-11-15 01:37:37.000000', NULL, 1),
(6222917, 919951, 4162, '<td valign="top">Great capture, love the blur and monochrome, fear that it won''t be liked by the majority due to the blur but great job</td>', 'Great capture, love the blur and monochrome, fear that it won''t be liked by the majority due to the blur but great job', '2010-11-15 01:38:14.000000', NULL, 1),
(6222918, 919824, 96751, '<td valign="top">Someone is having a REALLY good time.  Great detail on the wet fur, although whatever the surfboard (?) fragment on the left is distracting.</td>', 'Someone is having a REALLY good time.  Great detail on the wet fur, although whatever the surfboard (?) fragment on the left is distracting.', '2010-11-15 01:38:23.000000', NULL, 1),
(6222919, 919939, 96751, '<td valign="top">So very Twilight.  Great job on the lighting.</td>', 'So very Twilight.  Great job on the lighting.', '2010-11-15 01:38:49.000000', NULL, 1),
(6222920, 919862, 4162, '<td valign="top">What a great shot of a mundane object- how did you get your whites so white?!</td>', 'What a great shot of a mundane object- how did you get your whites so white?!', '2010-11-15 01:39:08.000000', NULL, 1),
(6222921, 919914, 96751, '<td valign="top">Awwwww.  Was he lost or just didn''t want to go inside?</td>', 'Awwwww.  Was he lost or just didn''t want to go inside?', '2010-11-15 01:39:17.000000', NULL, 1),
(6222922, 919312, 96751, '<td valign="top">Incredible detail!</td>', 'Incredible detail!', '2010-11-15 01:39:42.000000', NULL, 1),
(6222923, 920072, 4162, '<td valign="top">beautiful composition and colour-great 8</td>', 'beautiful composition and colour-great 8', '2010-11-15 01:39:57.000000', NULL, 1),
(6222925, 919552, 4162, '<td valign="top">I love the toning and shapes, I wonder if the soft focus detracts a little</td>', 'I love the toning and shapes, I wonder if the soft focus detracts a little', '2010-11-15 01:41:41.000000', NULL, 1),
(6222926, 920091, 4162, '<td valign="top">A timeless shot-looks like a book or album cover-great</td>', 'A timeless shot-looks like a book or album cover-great', '2010-11-15 01:42:27.000000', NULL, 1),
(6222927, 919866, 96751, '<td valign="top">I''ve been sitting, staring at this image for a long time.  I am hypnotized by it.  To me, this is a perfect image, offering tidbits of delight in every pixel, from the glistening trails across the lined path, the geometry of the bands of light, the glow of the lights seeping through the delicate branches, the fog, the figure, the graceful shapes they all create.  This is MY blue ribbon.</td>', 'I''ve been sitting, staring at this image for a long time.  I am hypnotized by it.  To me, this is a perfect image, offering tidbits of delight in every pixel, from the glistening trails across the lined path, the geometry of the bands of light, the glow of the lights seeping through the delicate branches, the fog, the figure, the graceful shapes they all create.  This is MY blue ribbon.', '2010-11-15 01:42:43.000000', NULL, 1),
(6222928, 920034, 96751, '<td valign="top">His feet are killing me.  Great blur.</td>', 'His feet are killing me.  Great blur.', '2010-11-15 01:43:07.000000', NULL, 1),
(6222929, 920067, 96751, '<td valign="top">This is so terrific.   The crop really makes the shot.</td>', 'This is so terrific.   The crop really makes the shot.', '2010-11-15 01:43:27.000000', NULL, 1),
(6222930, 919849, 4162, '<td valign="top">Cool shot and idea, the beans in the corner look like they could be a bit sharper as they are the main focal point</td>', 'Cool shot and idea, the beans in the corner look like they could be a bit sharper as they are the main focal point', '2010-11-15 01:43:31.000000', NULL, 1),
(6222931, 920041, 96751, '<td valign="top">Elegant abstract.</td>', 'Elegant abstract.', '2010-11-15 01:43:38.000000', NULL, 1),
(6222932, 920024, 96751, '<td valign="top">Oh my goodness.  A chrysanthemum never had such glorious lighting.  Spectacular.</td>', 'Oh my goodness.  A chrysanthemum never had such glorious lighting.  Spectacular.', '2010-11-15 01:44:18.000000', NULL, 1),
(6222933, 920015, 4162, '<td valign="top">Gorgeous shot, a real keepsake</td>', 'Gorgeous shot, a real keepsake', '2010-11-15 01:44:23.000000', NULL, 1),
(6222935, 919952, 96751, '<td valign="top">Is it just me, or does he look a bit like Liam Neeson?  I guess he really likes that horse...?</td>', 'Is it just me, or does he look a bit like Liam Neeson?  I guess he really likes that horse...?', '2010-11-15 01:44:46.000000', NULL, 1),
(6222938, 919168, 4162, '<td valign="top">what amazing editing-fantastic!</td>', 'what amazing editing-fantastic!', '2010-11-15 01:45:19.000000', NULL, 1),
(6222939, 919922, 96751, '<td valign="top">Wonderful.  I LOVE fog.  And the silhouette and reflection of the ranches is terrific.</td>', 'Wonderful.  I LOVE fog.  And the silhouette and reflection of the ranches is terrific.', '2010-11-15 01:45:22.000000', NULL, 1),
(6222940, 919408, 114285, '<td valign="top">Just stunning.</td>', 'Just stunning.', '2010-11-15 01:45:47.000000', NULL, 1),
(6222941, 920044, 96751, '<td valign="top">I love the lighting here, but I think the pp''ing is a little heavy handed for such a delicate subject.</td>', 'I love the lighting here, but I think the pp''ing is a little heavy handed for such a delicate subject.', '2010-11-15 01:45:59.000000', NULL, 1),
(6222942, 919845, 40391, '<td valign="top">I have no idea what that is (my first thought was a WWI gas mask) but it''s quirkiness, the use of DoF, composition and lighting makes for a great photo.  I like the title also - <strike>8</strike> come back to bump to a 9.</td>', 'I have no idea what that is (my first thought was a WWI gas mask) but it''s quirkiness, the use of DoF, composition and lighting makes for a great photo.  I like the title also - 8 come back to bump to a 9.', '2010-11-15 01:46:32.000000', NULL, 1),
(6222943, 919653, 4162, '<td valign="top">Beautiful focus and light-gorgeous</td>', 'Beautiful focus and light-gorgeous', '2010-11-15 01:46:38.000000', NULL, 1),
(6222944, 919974, 96751, '<td valign="top">Hi Ben!!!  Ah, the irony, the videographers being photographed by the delinquents.  The geometry and tonal range is fabulous.</td>', 'Hi Ben!!!  Ah, the irony, the videographers being photographed by the delinquents.  The geometry and tonal range is fabulous.', '2010-11-15 01:46:57.000000', NULL, 1),
(6222945, 919971, 96751, '<td valign="top">I know they''re fearless, but how did you get so close!!??</td>', 'I know they''re fearless, but how did you get so close!!??', '2010-11-15 01:47:17.000000', NULL, 1),
(6222946, 919408, 4162, '<td valign="top">Sooo gorgeous-love it!</td>', 'Sooo gorgeous-love it!', '2010-11-15 01:47:34.000000', NULL, 1),
(6222947, 919786, 96751, '<td valign="top">Fun image.  I just wish he stood out from the background a little more.</td>', 'Fun image.  I just wish he stood out from the background a little more.', '2010-11-15 01:47:38.000000', NULL, 1),
(6222948, 919863, 96751, '<td valign="top">Sweet!</td>', 'Sweet!', '2010-11-15 01:47:48.000000', NULL, 1),
(6222949, 919862, 96751, '<td valign="top">Hahaha.  I love when everyday objects look like art!</td>', 'Hahaha.  I love when everyday objects look like art!', '2010-11-15 01:48:14.000000', NULL, 1),
(6222950, 920015, 96751, '<td valign="top">This b/w is so marvelous.  Crisp pp''ing, and so much joy captured.</td>', 'This b/w is so marvelous.  Crisp pp''ing, and so much joy captured.', '2010-11-15 01:48:55.000000', NULL, 1),
(6222951, 919964, 96751, '<td valign="top">What a strange looking boy.  I love the dof. The lighting is very interesting - I like that it illuminates the subject indirectly.  I would love to see this in b/w</td>', 'What a strange looking boy.  I love the dof. The lighting is very interesting - I like that it illuminates the subject indirectly.  I would love to see this in b/w', '2010-11-15 01:50:14.000000', NULL, 1),
(6222952, 920010, 96751, '<td valign="top">Such graceful creatures.</td>', 'Such graceful creatures.', '2010-11-15 01:50:24.000000', NULL, 1),
(6222953, 920012, 96751, '<td valign="top">Very lovely shapes.</td>', 'Very lovely shapes.', '2010-11-15 01:50:37.000000', NULL, 1),
(6222956, 920010, 4162, '<td valign="top">What a beautiful shot, colour and light-good luck 9</td>', 'What a beautiful shot, colour and light-good luck 9', '2010-11-15 01:55:36.000000', NULL, 1),
(6222957, 919938, 4162, '<td valign="top">Love the yellow in the background, beautiful focus too</td>', 'Love the yellow in the background, beautiful focus too', '2010-11-15 01:56:06.000000', NULL, 1),
(6222958, 919815, 40391, '<td valign="top">The colours, textures and lighting are really lovely.  The fact that even with the title I can not work out what I''m looking at but still really enjoy looking (and that it meets the challenge) is why I''m giving this a 9.</td>', 'The colours, textures and lighting are really lovely.  The fact that even with the title I can not work out what I''m looking at but still really enjoy looking (and that it meets the challenge) is why I''m giving this a 9.', '2010-11-15 01:57:00.000000', NULL, 1),
(6222959, 919862, 10275, '<td valign="top">I love the simplicity of this image. Love the colour too. Good job with the border as it''s needed to contain the image. Well done.</td>', 'I love the simplicity of this image. Love the colour too. Good job with the border as it''s needed to contain the image. Well done.', '2010-11-15 01:58:30.000000', NULL, 1),
(6222960, 919643, 40391, '<td valign="top">I love the way you have made him NOT to pop but blend with the background.  Beautiful! 8</td>', 'I love the way you have made him NOT to pop but blend with the background.  Beautiful! 8', '2010-11-15 01:58:44.000000', NULL, 1),
(6222961, 919408, 10275, '<td valign="top">What a lovely portrait of a girl, with a beautiful tapestry of a background!</td>', 'What a lovely portrait of a girl, with a beautiful tapestry of a background!', '2010-11-15 01:59:09.000000', NULL, 1),
(6222963, 919974, 40391, '<td valign="top">Good eye and great capture. 8</td>', 'Good eye and great capture. 8', '2010-11-15 02:00:21.000000', NULL, 1),
(6222964, 919929, 10275, '<td valign="top">Wow, beautiful foreground textures and shapes. I wish there was more of the bottom than the top. Also, you need to clean your sensor, looks like you have some droplets of water in the sky. But beautiful image nonetheless.</td>', 'Wow, beautiful foreground textures and shapes. I wish there was more of the bottom than the top. Also, you need to clean your sensor, looks like you have some droplets of water in the sky. But beautiful image nonetheless.', '2010-11-15 02:00:54.000000', NULL, 1),
(6222965, 919952, 10275, '<td valign="top">Neat concept.</td>', 'Neat concept.', '2010-11-15 02:01:12.000000', NULL, 1),
(6222966, 919889, 10275, '<td valign="top">This is lovely. Love the fact it''s monotone. Great blending of details between the tree and the building.</td>', 'This is lovely. Love the fact it''s monotone. Great blending of details between the tree and the building.', '2010-11-15 02:01:39.000000', NULL, 1),
(6222967, 919637, 10275, '<td valign="top">Nice clean still life.</td>', 'Nice clean still life.', '2010-11-15 02:02:00.000000', NULL, 1),
(6222968, 920041, 4162, '<td valign="top">Love the simplicity-cool shot</td>', 'Love the simplicity-cool shot', '2010-11-15 02:02:17.000000', NULL, 1),
(6222969, 920067, 10275, '<td valign="top">Cool point of view.</td>', 'Cool point of view.', '2010-11-15 02:02:18.000000', NULL, 1),
(6222970, 919732, 4162, '<td valign="top">Love it!! Love the pose, the colours, the clothing-great shot</td>', 'Love it!! Love the pose, the colours, the clothing-great shot', '2010-11-15 02:03:22.000000', NULL, 1),
(6222971, 919824, 10275, '<td valign="top">Great image of the dog. He looks so cold :) The tail is in a perfect position. But I wish you have cropped the dark circular thing on the left.</td>', 'Great image of the dog. He looks so cold :) The tail is in a perfect position. But I wish you have cropped the dark circular thing on the left.', '2010-11-15 02:03:35.000000', NULL, 1),
(6222972, 919982, 10275, '<td valign="top">I just love the colour in this image. Nice and clean. Simplicity rules!</td>', 'I just love the colour in this image. Nice and clean. Simplicity rules!', '2010-11-15 02:04:20.000000', NULL, 1),
(6222973, 920089, 10275, '<td valign="top">Beautifully captured aerobatics. The smoke is just superb.</td>', 'Beautifully captured aerobatics. The smoke is just superb.', '2010-11-15 02:04:51.000000', NULL, 1),
(6222974, 919996, 4162, '<td valign="top">I would really like to see this in monochrome, the textures are great and could look even more striking in b/w...IMO</td>', 'I would really like to see this in monochrome, the textures are great and could look even more striking in b/w...IMO', '2010-11-15 02:05:40.000000', NULL, 1),
(6222975, 919542, 10275, '<td valign="top">Oh, this just cracks me up. I had to stop and actually investigate what it is I am looking at. Nice complimentary colours to the water.</td>', 'Oh, this just cracks me up. I had to stop and actually investigate what it is I am looking at. Nice complimentary colours to the water.', '2010-11-15 02:05:47.000000', NULL, 1),
(6222976, 920062, 4162, '<td valign="top">What a fabulous capture- could be top 3 easily!</td>', 'What a fabulous capture- could be top 3 easily!', '2010-11-15 02:06:29.000000', NULL, 1),
(6222977, 919733, 10275, '<td valign="top">Nice balance between the boat and the fisherman. Well exposed and colours are just perfect.</td>', 'Nice balance between the boat and the fisherman. Well exposed and colours are just perfect.', '2010-11-15 02:06:46.000000', NULL, 1),
(6222978, 919918, 10275, '<td valign="top">Just beautiful! I love the layers and colour tones.</td>', 'Just beautiful! I love the layers and colour tones.', '2010-11-15 02:07:27.000000', NULL, 1),
(6222979, 919792, 40391, '<td valign="top">The bokeh makes this shot.</td>', 'The bokeh makes this shot.', '2010-11-15 02:08:01.000000', NULL, 1),
(6222980, 919964, 10275, '<td valign="top">Very neat concept and I like how simple it is and how you composed the elements together. But the green is very overpowering and the boy''s face looks a bit plasticky. Still pretty good shot.</td>', 'Very neat concept and I like how simple it is and how you composed the elements together. But the green is very overpowering and the boy''s face looks a bit plasticky. Still pretty good shot.', '2010-11-15 02:08:51.000000', NULL, 1),
(6222982, 919786, 10275, '<td valign="top">Well composed and captured. Love the grey scale on this. But it has an "over-processed" HDR look, and perhaps cropping off the bottom blurry part would have made it into a stronger image.</td>', 'Well composed and captured. Love the grey scale on this. But it has an "over-processed" HDR look, and perhaps cropping off the bottom blurry part would have made it into a stronger image.', '2010-11-15 02:11:11.000000', NULL, 1),
(6222983, 920036, 10275, '<td valign="top">Great capture. He is perfectly sharp. My only distracting peeve is the bottom part where it is so blurry, my eyes keep focusing on it.</td>', 'Great capture. He is perfectly sharp. My only distracting peeve is the bottom part where it is so blurry, my eyes keep focusing on it.', '2010-11-15 02:12:55.000000', NULL, 1),
(6222984, 920017, 10275, '<td valign="top">Nice fun portrait, but the red is so overpowering her face. Also the eyes are very dark. I sort of keep looking into them trying to find some brighter part.</td>', 'Nice fun portrait, but the red is so overpowering her face. Also the eyes are very dark. I sort of keep looking into them trying to find some brighter part.', '2010-11-15 02:14:33.000000', NULL, 1),
(6222986, 919974, 10275, '<td valign="top">Neet architectural angle. Makes good shapes and grey tones. The composition is also very interesting.</td>', 'Neet architectural angle. Makes good shapes and grey tones. The composition is also very interesting.', '2010-11-15 02:15:32.000000', NULL, 1),
(6222987, 919359, 40391, '<td valign="top">Good idea and nice shot but I feel it didn''t need so much black space to portray being off center.</td>', 'Good idea and nice shot but I feel it didn''t need so much black space to portray being off center.', '2010-11-15 02:15:53.000000', NULL, 1),
(6222988, 920024, 10275, '<td valign="top">Beautiful, simple capture. The light is so very nice and the reflection is sharp. The bottom is a bit too dark. It is sort of disappearing into the mirror.</td>', 'Beautiful, simple capture. The light is so very nice and the reflection is sharp. The bottom is a bit too dark. It is sort of disappearing into the mirror.', '2010-11-15 02:17:08.000000', NULL, 1),
(6222989, 919734, 10275, '<td valign="top">It''s a bit messy for a composition. But the colours are nicely saturated and you handled the highlights quite well.</td>', 'It''s a bit messy for a composition. But the colours are nicely saturated and you handled the highlights quite well.', '2010-11-15 02:18:12.000000', NULL, 1),
(6222992, 920044, 10275, '<td valign="top">Nice HDR effect, but the lower left corner is a bit to dark and throws the image out of balance. Love the colours and textures.</td>', 'Nice HDR effect, but the lower left corner is a bit to dark and throws the image out of balance. Love the colours and textures.', '2010-11-15 02:19:09.000000', NULL, 1),
(6222993, 919934, 10275, '<td valign="top">Beautiful detail and composition.</td>', 'Beautiful detail and composition.', '2010-11-15 02:19:29.000000', NULL, 1),
(6222994, 919866, 40391, '<td valign="top">This is a really beautiful shot!  For me it would have been better without about a third of the bottom part of the shot but on of the best shots of the challenge. 9</td>', 'This is a really beautiful shot!  For me it would have been better without about a third of the bottom part of the shot but on of the best shots of the challenge. 9', '2010-11-15 02:19:54.000000', NULL, 1),
(6222995, 919892, 10275, '<td valign="top">Gorgeous! Love all the sharp edges and highlights.</td>', 'Gorgeous! Love all the sharp edges and highlights.', '2010-11-15 02:20:26.000000', NULL, 1),
(6222997, 919928, 40391, '<td valign="top">Sharp, colourful and interesting. 8.</td>', 'Sharp, colourful and interesting. 8.', '2010-11-15 02:20:45.000000', NULL, 1),
(6222998, 919971, 10275, '<td valign="top">Wow, this is stunning. Love the composition, colours, and the soft background. His eye has such detail. Beautiful nature image, but the bright orange border is not really necessary.</td>', 'Wow, this is stunning. Love the composition, colours, and the soft background. His eye has such detail. Beautiful nature image, but the bright orange border is not really necessary.', '2010-11-15 02:22:22.000000', NULL, 1),
(6222999, 919600, 10275, '<td valign="top">Lovely setup, lights and colours. I wish the composition were done is such way that there would be more space in front of her (on the left) than behind her on the right. And since the red fabric is leaning towards left and directly into the corner, it throws the image out of balance. Those are minor suggestion though, it is otherwise very stunning photo.</td>', 'Lovely setup, lights and colours. I wish the composition were done is such way that there would be more space in front of her (on the left) than behind her on the right. And since the red fabric is leaning towards left and directly into the corner, it throws the image out of balance. Those are minor suggestion though, it is otherwise very stunning photo.', '2010-11-15 02:24:59.000000', NULL, 1),
(6223001, 920073, 10275, '<td valign="top">Lovely and well handled image.  Love the way the flash froze the droplets of water. However I would have love seeing more of the water to the left of the swan. It is a bit left heavy.</td>', 'Lovely and well handled image.  Love the way the flash froze the droplets of water. However I would have love seeing more of the water to the left of the swan. It is a bit left heavy.', '2010-11-15 02:26:45.000000', NULL, 1),
(6223002, 919413, 10275, '<td valign="top">Beautiful and interesting image. Great sharpness in the clouds and lovely smooth building. The only thing I would suggest is to watch the amount of polarization when shooting images of this kind. The sky is very over-polarized and therefore way to dark for the rest of the image to balance it.</td>', 'Beautiful and interesting image. Great sharpness in the clouds and lovely smooth building. The only thing I would suggest is to watch the amount of polarization when shooting images of this kind. The sky is very over-polarized and therefore way to dark for the rest of the image to balance it.', '2010-11-15 02:29:05.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6223003, 919845, 10275, '<td valign="top">What an interesting image. So carefully done. Just right amount of sharpness in the leaves and mask. I really like the background. The circular speck highlights ad to this unique feel.</td>', 'What an interesting image. So carefully done. Just right amount of sharpness in the leaves and mask. I really like the background. The circular speck highlights ad to this unique feel.', '2010-11-15 02:30:40.000000', NULL, 1),
(6223004, 919985, 10275, '<td valign="top">Visual poetry! Soooo very beautiful. Reminds me of peaceful autumn days. I can hear wind chimes in the background :)))</td>', 'Visual poetry! Soooo very beautiful. Reminds me of peaceful autumn days. I can hear wind chimes in the background :)))', '2010-11-15 02:31:44.000000', NULL, 1),
(6223007, 920028, 10275, '<td valign="top">Fascinating. I am trying to guess what it is I am looking at. Looks like a giant bowl of pierogies :))</td>', 'Fascinating. I am trying to guess what it is I am looking at. Looks like a giant bowl of pierogies :))', '2010-11-15 02:34:52.000000', NULL, 1),
(6223011, 920071, 10275, '<td valign="top">This is very lovely. The light is so well handled, it makes the colours so realistic. Beautiful capture. The composition could have been done a way more interesting though (more on a diagonal). It is a bit too far to the left, needed a bit of space left of the flowers. Even just re-cropping third of the blackness away from the right.</td>', 'This is very lovely. The light is so well handled, it makes the colours so realistic. Beautiful capture. The composition could have been done a way more interesting though (more on a diagonal). It is a bit too far to the left, needed a bit of space left of the flowers. Even just re-cropping third of the blackness away from the right.', '2010-11-15 02:37:34.000000', NULL, 1),
(6223012, 919958, 10275, '<td valign="top">Nice effect of "spookyfying" the image. The surroundings are colourless, so it makes the tomb stand out. The more I look at it, the more I like it.</td>', 'Nice effect of "spookyfying" the image. The surroundings are colourless, so it makes the tomb stand out. The more I look at it, the more I like it.', '2010-11-15 02:38:55.000000', NULL, 1),
(6223014, 920098, 10275, '<td valign="top">Simplicity personified!</td>', 'Simplicity personified!', '2010-11-15 02:39:22.000000', NULL, 1),
(6223015, 919467, 10275, '<td valign="top">One of my favourites in this challenge. Beautiful composition and well handled light. Love the way  the sharpness falls off towards the back. This is so well done.</td>', 'One of my favourites in this challenge. Beautiful composition and well handled light. Love the way  the sharpness falls off towards the back. This is so well done.', '2010-11-15 02:40:19.000000', NULL, 1),
(6223016, 920021, 10275, '<td valign="top">Beautiful abstract. The colours are lovely. Interesting composition. Nice contrasts between dark and light. The only little part I wish wasn''t so dark is the top left corner.</td>', 'Beautiful abstract. The colours are lovely. Interesting composition. Nice contrasts between dark and light. The only little part I wish wasn''t so dark is the top left corner.', '2010-11-15 02:41:51.000000', NULL, 1),
(6223019, 918871, 10275, '<td valign="top">Nicely done portrait. Love the way you placed him so the eyes are on an angle. The tonality is really well handled too.</td>', 'Nicely done portrait. Love the way you placed him so the eyes are on an angle. The tonality is really well handled too.', '2010-11-15 02:44:39.000000', NULL, 1),
(6223022, 919654, 10275, '<td valign="top">I like the placement and the soft background. The flower is a bit overexposed, therefore you lost some of the texture of the bottom petals. It is also oversaturated a bit. If you tone it down, this would actually be a lovely flower shot.</td>', 'I like the placement and the soft background. The flower is a bit overexposed, therefore you lost some of the texture of the bottom petals. It is also oversaturated a bit. If you tone it down, this would actually be a lovely flower shot.', '2010-11-15 02:49:50.000000', NULL, 1),
(6223023, 919733, 40391, '<td valign="top">For me a little over saturated but the composition is great.</td>', 'For me a little over saturated but the composition is great.', '2010-11-15 02:50:22.000000', NULL, 1),
(6223024, 919395, 10275, '<td valign="top">Cute, but very very bright. Need toning down a bit.</td>', 'Cute, but very very bright. Need toning down a bit.', '2010-11-15 02:50:29.000000', NULL, 1),
(6223026, 919937, 10275, '<td valign="top">There seems to be a lot of pink and purple in this image, which makes it look a bit unnatural. The shirt stands out and is a nice colour, but the leaves shouldn''t be this blue. It is otherwise a very lovely image.</td>', 'There seems to be a lot of pink and purple in this image, which makes it look a bit unnatural. The shirt stands out and is a nice colour, but the leaves shouldn''t be this blue. It is otherwise a very lovely image.', '2010-11-15 02:52:14.000000', NULL, 1),
(6223027, 919497, 40391, '<td valign="top">Quite a nice composition but a different approach to the PP would have been better for me.</td>', 'Quite a nice composition but a different approach to the PP would have been better for me.', '2010-11-15 02:53:40.000000', NULL, 1),
(6223028, 919653, 10275, '<td valign="top">Lovely soft effect and the background is so nice. Love the way it glows. But my issue is with the white space on the left. It competes for attention with the couple. I wish it was not so bright.</td>', 'Lovely soft effect and the background is so nice. Love the way it glows. But my issue is with the white space on the left. It competes for attention with the couple. I wish it was not so bright.', '2010-11-15 02:54:09.000000', NULL, 1),
(6223029, 919704, 10275, '<td valign="top">Very interesting composition and toning.</td>', 'Very interesting composition and toning.', '2010-11-15 02:54:27.000000', NULL, 1),
(6223030, 920037, 10275, '<td valign="top">Cool idea, but the background is really not complementing this subject. Try toning it down to a more pleasing tone of green, not so neon looking.</td>', 'Cool idea, but the background is really not complementing this subject. Try toning it down to a more pleasing tone of green, not so neon looking.', '2010-11-15 02:55:30.000000', NULL, 1),
(6223031, 920012, 10275, '<td valign="top">Neat idea and lovely soft colors. I wish you had seamless background though. It would make this nice image into a perfect one. All you need is a bigger piece of soft blue paper and bend it without creasing it to make it into continuing piece.</td>', 'Neat idea and lovely soft colors. I wish you had seamless background though. It would make this nice image into a perfect one. All you need is a bigger piece of soft blue paper and bend it without creasing it to make it into continuing piece.', '2010-11-15 02:58:18.000000', NULL, 1),
(6223033, 919406, 40391, '<td valign="top">Interesting perspective and good use of B&amp;W but I feel your title needs a little more explanation as right now I find it a little offensive. However, I know my lack of knowledge in such things is somewhat poor that I''m voting without my probable prejudice. 6.<br/> <br/>* If the title is what I originally thought then I reserve the right to have my vote be recognised as a 2!</td>', 'Interesting perspective and good use of B&W but I feel your title needs a little more explanation as right now I find it a little offensive. However, I know my lack of knowledge in such things is somewhat poor that I''m voting without my probable prejudice. 6. * If the title is what I originally thought then I reserve the right to have my vote be recognised as a 2!', '2010-11-15 03:03:20.000000', NULL, 1),
(6223035, 919138, 40391, '<td valign="top">I see a shot like this and the way it''s processed and I think of <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=83313" rel="nofollow" target="_blank">Yo_Spiff</a>.  I really like the PP, it meets the challenge nicely but it''s the colour that does it for me. 7</td>', 'I see a shot like this and the way it''s processed and I think of  Yo_Spiff.  I really like the PP, it meets the challenge nicely but it''s the colour that does it for me. 7', '2010-11-15 03:06:57.000000', NULL, 1),
(6223036, 919928, 10275, '<td valign="top">Great idea and well executed. It reminds me of a chinese painting. The dots on the right look like chinese alphabet in columns.</td>', 'Great idea and well executed. It reminds me of a chinese painting. The dots on the right look like chinese alphabet in columns.', '2010-11-15 03:07:22.000000', NULL, 1),
(6223037, 919785, 10275, '<td valign="top">Very neat high-key image. Composition is dead on. The lines of the fence in contrast with the boy making a triangle with his legs. The only suggestion how to improve this photo would be to sweep the leaves off. Without the distractions, this would be one of my top images.</td>', 'Very neat high-key image. Composition is dead on. The lines of the fence in contrast with the boy making a triangle with his legs. The only suggestion how to improve this photo would be to sweep the leaves off. Without the distractions, this would be one of my top images.', '2010-11-15 03:09:33.000000', NULL, 1),
(6223038, 919957, 10275, '<td valign="top">Lovely concept. Striking contrast with the bark of the old tree. Looks like it was burned. I wish the background was a bit more blurred.</td>', 'Lovely concept. Striking contrast with the bark of the old tree. Looks like it was burned. I wish the background was a bit more blurred.', '2010-11-15 03:11:27.000000', NULL, 1),
(6223039, 919860, 10275, '<td valign="top">Lovely subject and compostion, but is overexposed a bit and lacks overall sharpness. I would have zoomed more in, to see his face.</td>', 'Lovely subject and compostion, but is overexposed a bit and lacks overall sharpness. I would have zoomed more in, to see his face.', '2010-11-15 03:12:48.000000', NULL, 1),
(6223043, 919257, 10275, '<td valign="top">Nice perspective and sharpness. The border is too thick for this image. It makes it heavy.</td>', 'Nice perspective and sharpness. The border is too thick for this image. It makes it heavy.', '2010-11-15 03:24:36.000000', NULL, 1),
(6223044, 919789, 10275, '<td valign="top">Beautiful. Such a neat idea. I would have cropped off the crampled part of the pillow or use ironed sheet to make it nice a smooth. It distracts from the baby a bit.</td>', 'Beautiful. Such a neat idea. I would have cropped off the crampled part of the pillow or use ironed sheet to make it nice a smooth. It distracts from the baby a bit.', '2010-11-15 03:26:17.000000', NULL, 1),
(6223046, 919950, 10275, '<td valign="top">Perfect expression.</td>', 'Perfect expression.', '2010-11-15 03:33:16.000000', NULL, 1),
(6223049, 919312, 10275, '<td valign="top">This is very beautiful composition and clarity. Simple, yet complex.</td>', 'This is very beautiful composition and clarity. Simple, yet complex.', '2010-11-15 03:35:39.000000', NULL, 1),
(6223051, 919792, 10275, '<td valign="top">Stunning product photography. Well lit, and I really like how the specular highlights add to the glamor of this shot.</td>', 'Stunning product photography. Well lit, and I really like how the specular highlights add to the glamor of this shot.', '2010-11-15 03:37:48.000000', NULL, 1),
(6223052, 919497, 10275, '<td valign="top">Auch, the colour is really overpowering the whole image. If you tone it down a bit, this could actually be a lovely shot.</td>', 'Auch, the colour is really overpowering the whole image. If you tone it down a bit, this could actually be a lovely shot.', '2010-11-15 03:38:51.000000', NULL, 1),
