(6223235, 919408, 15711, '<td valign="top">Oh this is gorgeous. I love her opposing red knitted cap with the complimentary yellow of the field and blue of the sky.  This is perfectly done.</td>', 'Oh this is gorgeous. I love her opposing red knitted cap with the complimentary yellow of the field and blue of the sky.  This is perfectly done.', '2010-11-15 09:22:15.000000', NULL, 1),
(6223236, 919928, 15711, '<td valign="top">You cannot go wrong with a leaf.  The bokeh is gorgeous and I like the drops in the foreground being as focused as the leaf itself.  Really pretty.</td>', 'You cannot go wrong with a leaf.  The bokeh is gorgeous and I like the drops in the foreground being as focused as the leaf itself.  Really pretty.', '2010-11-15 09:22:41.000000', NULL, 1),
(6223237, 920091, 15711, '<td valign="top">Really moody.  :)</td>', 'Really moody.  :)', '2010-11-15 09:23:02.000000', NULL, 1),
(6223239, 919786, 15711, '<td valign="top">Interesting juxtaposition with the guy flipping his board and the memorial wreath.  This can really tell a story.  Lots of nice textures.  Good tones.</td>', 'Interesting juxtaposition with the guy flipping his board and the memorial wreath.  This can really tell a story.  Lots of nice textures.  Good tones.', '2010-11-15 09:23:46.000000', NULL, 1),
(6223241, 920024, 15711, '<td valign="top">I like the subdued lighting.  Mums of all kinds are so beautiful with their multi-petaled blooms!</td>', 'I like the subdued lighting.  Mums of all kinds are so beautiful with their multi-petaled blooms!', '2010-11-15 09:24:29.000000', NULL, 1),
(6223243, 919971, 15711, '<td valign="top">Perfect focus.  Love the purples!!</td>', 'Perfect focus.  Love the purples!!', '2010-11-15 09:24:58.000000', NULL, 1),
(6223244, 919946, 15711, '<td valign="top">This is lovely. I always think of a ballet dancer''s hands when I see a flowery stem arched over like that.  The complimentary colors really work perfectly together as they go in and out of focus.</td>', 'This is lovely. I always think of a ballet dancer''s hands when I see a flowery stem arched over like that.  The complimentary colors really work perfectly together as they go in and out of focus.', '2010-11-15 09:25:38.000000', NULL, 1),
(6223245, 919937, 15711, '<td valign="top">Darling.  I wish she were looking at the camera.  The colors seems to be a bit purple, but maybe that was your intent. :)</td>', 'Darling.  I wish she were looking at the camera.  The colors seems to be a bit purple, but maybe that was your intent. :)', '2010-11-15 09:26:15.000000', NULL, 1),
