(6223744, 919839, 36843, '<td valign="top">ok, this is very cool and I want to see the set up. I would like to see the tomato and knife sprayed with water</td>', 'ok, this is very cool and I want to see the set up. I would like to see the tomato and knife sprayed with water', '2010-11-15 17:19:04.000000', NULL, 1),
(6223748, 919556, 47470, '<td valign="top">I wish this were a little sharper.</td>', 'I wish this were a little sharper.', '2010-11-15 17:22:22.000000', NULL, 1),
(6223751, 918928, 47470, '<td valign="top">Perfect detail on the hair and wings.</td>', 'Perfect detail on the hair and wings.', '2010-11-15 17:24:41.000000', NULL, 1),
(6223754, 919789, 47470, '<td valign="top">The wrinkles on the background are killing me since wrinkles are so easy to fix.  You should have either:<br/>- used a shallower depth of field.<br/>- pulled the background away from the baby.<br/>- modified the light so no light touched the background.<br/>- ironed the background : )</td>', 'The wrinkles on the background are killing me since wrinkles are so easy to fix.  You should have either:- used a shallower depth of field.- pulled the background away from the baby.- modified the light so no light touched the background.- ironed the background : )', '2010-11-15 17:26:50.000000', NULL, 1),
(6223758, 920044, 108069, '<td valign="top">Lovely image. Processing really adds to the texture here. Lighting is exceptionally well done. Wonderful colors, tones and shades. Composition is of course right on. Excellent work.</td>', 'Lovely image. Processing really adds to the texture here. Lighting is exceptionally well done. Wonderful colors, tones and shades. Composition is of course right on. Excellent work.', '2010-11-15 17:27:46.000000', NULL, 1),
(6223760, 919749, 47470, '<td valign="top">The extra greenery in the top left adds a wonderful border and helps balance the image.</td>', 'The extra greenery in the top left adds a wonderful border and helps balance the image.', '2010-11-15 17:28:21.000000', NULL, 1),
(6223762, 919542, 108069, '<td valign="top">Pretty damn funny. The processing really makes it look like an old photo so that fits perfectly.</td>', 'Pretty damn funny. The processing really makes it look like an old photo so that fits perfectly.', '2010-11-15 17:28:39.000000', NULL, 1),
(6223764, 919839, 108069, '<td valign="top">Your work continues to amaze me. Again, perfectly lit, razor sharp, excellent display of motion, and another uniquely creative and this time humorous scene. And every time it just looks like you have so much fun with all of it. Dude, you''re an inspiration.</td>', 'Your work continues to amaze me. Again, perfectly lit, razor sharp, excellent display of motion, and another uniquely creative and this time humorous scene. And every time it just looks like you have so much fun with all of it. Dude, you''re an inspiration.', '2010-11-15 17:29:16.000000', NULL, 1),
(6223766, 919889, 47470, '<td valign="top">Wonderful take on such a well-known building.  This creates a mood so different than most pictures of this building that it gives back a little spice!</td>', 'Wonderful take on such a well-known building.  This creates a mood so different than most pictures of this building that it gives back a little spice!', '2010-11-15 17:29:46.000000', NULL, 1),
(6223767, 919928, 108069, '<td valign="top">Very nice shot. Nice composition, great colors and very nice lack of depth. Well done.</td>', 'Very nice shot. Nice composition, great colors and very nice lack of depth. Well done.', '2010-11-15 17:30:03.000000', NULL, 1),
(6223768, 919430, 47470, '<td valign="top">Beautiful clarity and sharpness.  Love the tones in the background too.</td>', 'Beautiful clarity and sharpness.  Love the tones in the background too.', '2010-11-15 17:30:42.000000', NULL, 1),
(6223773, 919541, 47470, '<td valign="top">Beautiful, lively shot, with an extra point since the subject is so common, yet still captured in an interesting way.</td>', 'Beautiful, lively shot, with an extra point since the subject is so common, yet still captured in an interesting way.', '2010-11-15 17:32:32.000000', NULL, 1),
(6223774, 919552, 47470, '<td valign="top">I wish this was sharp all the way through so the textures could play off one another.</td>', 'I wish this was sharp all the way through so the textures could play off one another.', '2010-11-15 17:34:03.000000', NULL, 1),
(6223780, 920037, 47470, '<td valign="top">Wow, that''s <i>some</i> green.  I didn''t get it until I read the title.<br/>I wish you had used a duller, darker, more subtle green.  When you think of tea, you think of calm, soothing colors, not neon, so the green should have matched better.</td>', 'Wow, that''s some green.  I didn''t get it until I read the title.I wish you had used a duller, darker, more subtle green.  When you think of tea, you think of calm, soothing colors, not neon, so the green should have matched better.', '2010-11-15 17:36:14.000000', NULL, 1),
(6223786, 919839, 47470, '<td valign="top">What a lovely capture, full of color and movement.  Very well executed.</td>', 'What a lovely capture, full of color and movement.  Very well executed.', '2010-11-15 17:39:50.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6223787, 920010, 47470, '<td valign="top">This looks like something from a fairytale.  I half expected to see a horn coming out from the white horse''s head : )</td>', 'This looks like something from a fairytale.  I half expected to see a horn coming out from the white horse''s head : )', '2010-11-15 17:42:32.000000', NULL, 1),
(6223788, 919136, 47470, '<td valign="top">The texture of the background is amazing.  The image wouldn''t be as interesting without it.  Lovely colors.</td>', 'The texture of the background is amazing.  The image wouldn''t be as interesting without it.  Lovely colors.', '2010-11-15 17:43:39.000000', NULL, 1),
(6223791, 919942, 47470, '<td valign="top">Gorgeous capture.  The shutter speed is perfect--pretty sharp, but just slow enough to get some movement from the wave, which reinforces the title and the message.  Very well done.</td>', 'Gorgeous capture.  The shutter speed is perfect--pretty sharp, but just slow enough to get some movement from the wave, which reinforces the title and the message.  Very well done.', '2010-11-15 17:46:30.000000', NULL, 1),
(6223793, 919846, 47470, '<td valign="top">Since this is advanced editing, I wish you had darkened the top left corner a bit.  Otherwise, this is beautiful.</td>', 'Since this is advanced editing, I wish you had darkened the top left corner a bit.  Otherwise, this is beautiful.', '2010-11-15 17:48:03.000000', NULL, 1),
(6223795, 920044, 47470, '<td valign="top">I''m loving the colors on this.  Bright, yet dull at the same time, just the way autumn should be.</td>', 'I''m loving the colors on this.  Bright, yet dull at the same time, just the way autumn should be.', '2010-11-15 17:49:29.000000', NULL, 1),
(6223800, 920025, 121073, '<td valign="top">I appreciate the creativity, but this doesn''t work for me - I''m looking all over the place :(.</td>', 'I appreciate the creativity, but this doesn''t work for me - I''m looking all over the place :(.', '2010-11-15 17:59:59.000000', NULL, 1),
(6223801, 919974, 121073, '<td valign="top">Love it, great angle!</td>', 'Love it, great angle!', '2010-11-15 18:00:13.000000', NULL, 1),
(6223802, 919936, 121073, '<td valign="top">Nice! I would''ve preferred the background a little less distracting.</td>', 'Nice! I would''ve preferred the background a little less distracting.', '2010-11-15 18:00:51.000000', NULL, 1),
(6223804, 919953, 121073, '<td valign="top">Great colours!</td>', 'Great colours!', '2010-11-15 18:01:32.000000', NULL, 1),
(6223806, 919734, 121073, '<td valign="top">This isn''t that interesting to me.<br/>The tree(/rings) is the off-centre subject, but I (the viewer) don''t really care about the tree :(</td>', 'This isn''t that interesting to me.The tree(/rings) is the off-centre subject, but I (the viewer) don''t really care about the tree :(', '2010-11-15 18:03:03.000000', NULL, 1),
(6223810, 920093, 121073, '<td valign="top">Very cool!</td>', 'Very cool!', '2010-11-15 18:03:50.000000', NULL, 1),
(6223818, 919408, 23317, '<td valign="top">Fantastic shot.  Love the softness in the grass and the mountains.  Her look is perfect and so is the hat.<br/> <br/>If I''m looking for something to nitpick, some of the clouds could use some more definition, but it''s such a beautiful image I don''t think it matters.</td>', 'Fantastic shot.  Love the softness in the grass and the mountains.  Her look is perfect and so is the hat. If I''m looking for something to nitpick, some of the clouds could use some more definition, but it''s such a beautiful image I don''t think it matters.', '2010-11-15 18:07:46.000000', NULL, 1),
(6223822, 919789, 23317, '<td valign="top">I really like you''re idea here and like part of the composition... the baby at the bottom of the image makes it perfect for the title.  I also like the sleeping position of the baby with those precious little feet tucked under the bottom.  The arm position and the sleeping face are all fantastic.<br/> <br/>For me, what takes away from the parts that I like is the executive of a few things and some other composition factors.  While the pillow may be a soft place for the baby to rest, it hides part of the baby''s face, which looks a bit odd.  The black sheet in the background could use a little work to make the background disappear.  The foreground gray pill has some of those same issues.  Perhaps using something softer, without wrinkles could have produced a less noticeable results so that we could focus on that precious baby.  But just my opinions of course.</td>', 'I really like you''re idea here and like part of the composition... the baby at the bottom of the image makes it perfect for the title.  I also like the sleeping position of the baby with those precious little feet tucked under the bottom.  The arm position and the sleeping face are all fantastic. For me, what takes away from the parts that I like is the executive of a few things and some other composition factors.  While the pillow may be a soft place for the baby to rest, it hides part of the baby''s face, which looks a bit odd.  The black sheet in the background could use a little work to make the background disappear.  The foreground gray pill has some of those same issues.  Perhaps using something softer, without wrinkles could have produced a less noticeable results so that we could focus on that precious baby.  But just my opinions of course.', '2010-11-15 18:14:15.000000', NULL, 1),
(6223831, 919811, 121073, '<td valign="top">My thoughts: <br/>*There is a lot of noise in the lower/darker parts of the picture, was this shot underxposed and did you have to increase the brightness afterwards?<br/>*It''s not very interesting :(</td>', 'My thoughts: *There is a lot of noise in the lower/darker parts of the picture, was this shot underxposed and did you have to increase the brightness afterwards?*It''s not very interesting :(', '2010-11-15 18:22:18.000000', NULL, 1),
