(6229684, 919866, 23394, '<td valign="top">simply wonderful, nella!  congrats!</td>', 'simply wonderful, nella!  congrats!', '2010-11-22 06:39:46.000000', NULL, 0),
(6229693, 919839, 114969, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by h2:</b></div><hr/><i> Excellent setup, lighting and execution again, Christophe. Congrats on the red (what else could it be). Some remarks I''d have, though: there should be tomato juice on the knife and overall I don''t find this to be an off-centered composition. Great image, anyway. </i></td></tr></table> <br/> <br/>Thanks for your comment Oliver! I do agree with you: usually I compose the shot from the challenge''s topic, but this one was done the other way. It just popped in my head, and then I thought it could fit in this challenge, even if the off-centered elements tend to balance each other.<br/> <br/>As for the juice on knife, or even spraying from the slices, I tried... and failed :) We need more expert editing challenges! ;-)</td>', 'Originally posted by h2: Excellent setup, lighting and execution again, Christophe. Congrats on the red (what else could it be). Some remarks I''d have, though: there should be tomato juice on the knife and overall I don''t find this to be an off-centered composition. Great image, anyway.   Thanks for your comment Oliver! I do agree with you: usually I compose the shot from the challenge''s topic, but this one was done the other way. It just popped in my head, and then I thought it could fit in this challenge, even if the off-centered elements tend to balance each other. As for the juice on knife, or even spraying from the slices, I tried... and failed :) We need more expert editing challenges! ;-)', '2010-11-22 07:10:44.000000', NULL, 0),
(6229694, 919991, 81362, '<td valign="top">Meets the topic without doubt, and hits on two meanings of composition with elegant simplicity. Mild distortion of the upper staff lines adds a subtle visual emphasis to the strain of working with originality. Had this in my top three.</td>', 'Meets the topic without doubt, and hits on two meanings of composition with elegant simplicity. Mild distortion of the upper staff lines adds a subtle visual emphasis to the strain of working with originality. Had this in my top three.', '2010-11-22 07:19:58.000000', NULL, 0),
(6229697, 919839, 74559, '<td valign="top">Another fantastic and fun image, congrats on the ribbon!</td>', 'Another fantastic and fun image, congrats on the ribbon!', '2010-11-22 07:24:29.000000', NULL, 0),
(6229699, 919913, 23484, '<td valign="top">Nice composition Nancy.  I like the sky.</td>', 'Nice composition Nancy.  I like the sky.', '2010-11-22 07:26:39.000000', NULL, 0),
(6229700, 919866, 74559, '<td valign="top">How wonderful to see an image like this on the front page! It is absolutely fantastic. Dark, moody, like an old spy movie, something is going down here...congrats on the blue!!</td>', 'How wonderful to see an image like this on the front page! It is absolutely fantastic. Dark, moody, like an old spy movie, something is going down here...congrats on the blue!!', '2010-11-22 07:28:57.000000', NULL, 0),
(6229701, 919797, 81362, '<td valign="top">Excellent composition for the challenge (no verticle or horizontal symmetry, people gathered away from center, and bright area clearly off-center) with lots of ambiguous figures to stimulate thinking about alternative meanings/interpretations. Maybe the grain is stronger than necessary, but it is very hard to understand why this would receive 29 votes of 3 or lower.</td>', 'Excellent composition for the challenge (no verticle or horizontal symmetry, people gathered away from center, and bright area clearly off-center) with lots of ambiguous figures to stimulate thinking about alternative meanings/interpretations. Maybe the grain is stronger than necessary, but it is very hard to understand why this would receive 29 votes of 3 or lower.', '2010-11-22 07:29:39.000000', NULL, 0),
(6229702, 919985, 66597, '<td valign="top">Colleen, as usual I am drawn to your work. This is fabulous.</td>', 'Colleen, as usual I am drawn to your work. This is fabulous.', '2010-11-22 07:29:52.000000', NULL, 0),
(6229707, 919908, 81362, '<td valign="top">The water drops give this a sense of cold, at least from their shapes and the amount of white. Nice isolation of main subject. The branch, pointing from right to left, moves the eye in the opposite direction from normal reading pattern. While this gives some tension, it would be interesting to try it flipped horizontally to see how that feels.</td>', 'The water drops give this a sense of cold, at least from their shapes and the amount of white. Nice isolation of main subject. The branch, pointing from right to left, moves the eye in the opposite direction from normal reading pattern. While this gives some tension, it would be interesting to try it flipped horizontally to see how that feels.', '2010-11-22 07:36:44.000000', NULL, 0),
(6229708, 920074, 81362, '<td valign="top">Actually holds interest for me, but compoistion might be stronger with upper white space cropped closer to the subject.</td>', 'Actually holds interest for me, but compoistion might be stronger with upper white space cropped closer to the subject.', '2010-11-22 07:38:31.000000', NULL, 0),
(6229711, 920028, 76335, '<td valign="top">clearing smoke<br/>alien bodies<br/>piled up<br/>except for one<br/>whose time was short</td>', 'clearing smokealien bodiespiled upexcept for onewhose time was short', '2010-11-22 07:40:37.000000', NULL, 0),
(6229712, 919866, 81530, '<td valign="top">Way to go! Congratulations :)</td>', 'Way to go! Congratulations :)', '2010-11-22 07:40:57.000000', NULL, 0),
(6229713, 919839, 81530, '<td valign="top">You are a photography machine. Keep em coming!</td>', 'You are a photography machine. Keep em coming!', '2010-11-22 07:41:59.000000', NULL, 0),
(6229715, 919971, 81530, '<td valign="top">You never cease to amaze me!</td>', 'You never cease to amaze me!', '2010-11-22 07:42:32.000000', NULL, 0),
(6229718, 919785, 81362, '<td valign="top">Masterful use of light and thoughtful capture of expression. The scattered leaves echo the sense of adolescent transition, and convert this from a standard portrait to a visual essay on changes as life goes on. All the more poignent knowing the dramatic changes you have experienced this year. Amazing image.</td>', 'Masterful use of light and thoughtful capture of expression. The scattered leaves echo the sense of adolescent transition, and convert this from a standard portrait to a visual essay on changes as life goes on. All the more poignent knowing the dramatic changes you have experienced this year. Amazing image.', '2010-11-22 07:46:19.000000', NULL, 0),
(6229724, 920012, 121073, '<td valign="top">@passions: Not intentionally ;)</td>', '@passions: Not intentionally ;)', '2010-11-22 07:58:10.000000', NULL, 0),
