(6229756, 920053, 15711, '<td valign="top">Really???  WOW - I gave it a 9.</td>', 'Really???  WOW - I gave it a 9.', '2010-11-22 08:29:38.000000', NULL, 0),
(6229757, 919862, 15711, '<td valign="top">This is way underrated.  I loved it.</td>', 'This is way underrated.  I loved it.', '2010-11-22 08:29:53.000000', NULL, 0),
(6229788, 919413, 100831, '<td valign="top">wonderful abstract and reflection! Great job with the color. Congratulations on the high finish - well deserved. I never got to this in voting because the site shut down last night but it would have been a high mark from me for sure!</td>', 'wonderful abstract and reflection! Great job with the color. Congratulations on the high finish - well deserved. I never got to this in voting because the site shut down last night but it would have been a high mark from me for sure!', '2010-11-22 08:57:10.000000', NULL, 0),
(6229789, 919408, 100831, '<td valign="top">terrific shot - wonderful perspective and such rich color - congrats on TT!</td>', 'terrific shot - wonderful perspective and such rich color - congrats on TT!', '2010-11-22 08:59:34.000000', NULL, 0),
(6229790, 919866, 30982, '<td valign="top">Wow - how gorgeous!  Huge congratulations!  Wonderful to see such a moody monochromatic shot get the recognition it deserves.  Everything here came together perfectly - that tree on the right is just the right shape, the leaves on the ground and the reflected light drizzling through, the fog swallowing your stranger.  And the composition is dead-on to take advantage of all these elements.  Wonderful!</td>', 'Wow - how gorgeous!  Huge congratulations!  Wonderful to see such a moody monochromatic shot get the recognition it deserves.  Everything here came together perfectly - that tree on the right is just the right shape, the leaves on the ground and the reflected light drizzling through, the fog swallowing your stranger.  And the composition is dead-on to take advantage of all these elements.  Wonderful!', '2010-11-22 09:01:25.000000', NULL, 0),
(6229791, 920010, 61222, '<td valign="top">Congrats Sis on your Top 5 great image.</td>', 'Congrats Sis on your Top 5 great image.', '2010-11-22 09:01:56.000000', NULL, 0),
(6229796, 919839, 85430, '<td valign="top">hahaha. i gave this a 10 as usual. i did not comment during voting coz im getting tired of saying "Awesome! Great shot!" week after week after week coz you never seem to run out of ideas of outdoing yourself. You''re the best and you''re still getting better. thanks for always sharing your lighting setup and other details of your shot.<br/> <br/>oh by the way, Awesome! Great shot!</td>', 'hahaha. i gave this a 10 as usual. i did not comment during voting coz im getting tired of saying "Awesome! Great shot!" week after week after week coz you never seem to run out of ideas of outdoing yourself. You''re the best and you''re still getting better. thanks for always sharing your lighting setup and other details of your shot. oh by the way, Awesome! Great shot!', '2010-11-22 09:07:17.000000', NULL, 0),
(6229800, 919866, 114969, '<td valign="top">Fantastic shot, the subtle shades are just perfect. I love these kind of lonely moods. Congratulations on your well deserved ribbon!</td>', 'Fantastic shot, the subtle shades are just perfect. I love these kind of lonely moods. Congratulations on your well deserved ribbon!', '2010-11-22 09:16:54.000000', NULL, 0),
(6229804, 919971, 114969, '<td valign="top">The composition and colors are obviously perfect, and the sharpness is absolutely impressive. <br/>An outstanding example of modern equipments high ISO capabilities. Congratulations!</td>', 'The composition and colors are obviously perfect, and the sharpness is absolutely impressive. An outstanding example of modern equipments high ISO capabilities. Congratulations!', '2010-11-22 09:22:22.000000', NULL, 0),
(6229806, 920089, 121949, '<td valign="top">I think this one was underappreciated. I gave it a 7!</td>', 'I think this one was underappreciated. I gave it a 7!', '2010-11-22 09:24:49.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6229814, 919866, 61222, '<td valign="top">Very cool capture. Congrats on your BLUE!!</td>', 'Very cool capture. Congrats on your BLUE!!', '2010-11-22 09:32:12.000000', NULL, 0),
(6229821, 919866, 24454, '<td valign="top">Oh, I LOOOOVE this photo!  I am so PROUD of the voters for awarding this with its highest honor.  There was a time when the voting masses weren''t quite artistic enough to appreciate the artistry of something this amazing! CONGRATULATIONS!</td>', 'Oh, I LOOOOVE this photo!  I am so PROUD of the voters for awarding this with its highest honor.  There was a time when the voting masses weren''t quite artistic enough to appreciate the artistry of something this amazing! CONGRATULATIONS!', '2010-11-22 09:52:24.000000', NULL, 0),
(6229828, 919839, 24454, '<td valign="top">Amazing!  Thanks for telling us your lighting set up too.  I never get bored with self-portraits -- because with self-portraits the subject is mastering the perfect vision of the photographer -- which as a photographer, I find it so hard to do when you''re trying to get someone <i>else</i> to see it.  This is perfection!</td>', 'Amazing!  Thanks for telling us your lighting set up too.  I never get bored with self-portraits -- because with self-portraits the subject is mastering the perfect vision of the photographer -- which as a photographer, I find it so hard to do when you''re trying to get someone else to see it.  This is perfection!', '2010-11-22 09:56:29.000000', NULL, 0),
(6229833, 919971, 24454, '<td valign="top">Oh how inspiring your hummingbirds are!  You have such beautiful ones there.  I love LOVE hummingbirds, but ours are generally brown all over, with sometimes just a slight touch of green on their backs. Congratulations!  This is amazing!</td>', 'Oh how inspiring your hummingbirds are!  You have such beautiful ones there.  I love LOVE hummingbirds, but ours are generally brown all over, with sometimes just a slight touch of green on their backs. Congratulations!  This is amazing!', '2010-11-22 10:00:19.000000', NULL, 0),
(6229837, 919408, 24454, '<td valign="top">Auuuugh!  This is beautiful!  You are BLESSED to live surrounded by mountains.  Where is that?   It reminds me of my beloved Rocky Mountains in the distance.</td>', 'Auuuugh!  This is beautiful!  You are BLESSED to live surrounded by mountains.  Where is that?   It reminds me of my beloved Rocky Mountains in the distance.', '2010-11-22 10:02:47.000000', NULL, 0),
(6229844, 920091, 103142, '<td valign="top">I thought this was an excellent shot -- I gave it an 8. :D</td>', 'I thought this was an excellent shot -- I gave it an 8. :D', '2010-11-22 10:05:07.000000', NULL, 0),
(6229845, 920010, 24454, '<td valign="top">Last night when I was looking for the challenge result, but couldn''t see the images, I KNEW I had to come back and see what kind of horse beauty was gracing the front page with your 5th place entry.  And oh how it did not disappoint!  This is magical!!  Congratulations!</td>', 'Last night when I was looking for the challenge result, but couldn''t see the images, I KNEW I had to come back and see what kind of horse beauty was gracing the front page with your 5th place entry.  And oh how it did not disappoint!  This is magical!!  Congratulations!', '2010-11-22 10:06:22.000000', NULL, 0),
(6229847, 919435, 24454, '<td valign="top">THAT is VERY cool!  The minimalist artistry is brilliant!</td>', 'THAT is VERY cool!  The minimalist artistry is brilliant!', '2010-11-22 10:07:20.000000', NULL, 0),
(6229851, 918936, 24454, '<td valign="top">A beautiful specimen indeed, made even more beautiful by the master''s touh!</td>', 'A beautiful specimen indeed, made even more beautiful by the master''s touh!', '2010-11-22 10:08:48.000000', NULL, 0),
(6229854, 919917, 24454, '<td valign="top">:)  I love it!  I didn''t notice the looker at first, but then when you spot it, it''s like a secret gem that totally <i>makes</i> the photo!</td>', ':)  I love it!  I didn''t notice the looker at first, but then when you spot it, it''s like a secret gem that totally makes the photo!', '2010-11-22 10:09:56.000000', NULL, 0),
(6229855, 918871, 24454, '<td valign="top">Oooooh, LOVE that composition!  Nice job, Lydia!</td>', 'Oooooh, LOVE that composition!  Nice job, Lydia!', '2010-11-22 10:10:25.000000', NULL, 0),
(6229858, 919952, 24454, '<td valign="top">I LOVE this!  The light and color tones are AMAZING!  Like a bronze god :)<br/> <br/></td>', 'I LOVE this!  The light and color tones are AMAZING!  Like a bronze god :) ', '2010-11-22 10:12:18.000000', NULL, 0),
(6229859, 919732, 24454, '<td valign="top">Awww!  This is awesome!  I''m disappointed that it wasn''t given higher praise for the artistry and interest.  I love it!<br/></td>', 'Awww!  This is awesome!  I''m disappointed that it wasn''t given higher praise for the artistry and interest.  I love it!', '2010-11-22 10:14:04.000000', NULL, 0),
(6229864, 919408, 121949, '<td valign="top">Yes, Rocky mountains, I am surrounded by them here in the little valley I live in in Utah.</td>', 'Yes, Rocky mountains, I am surrounded by them here in the little valley I live in in Utah.', '2010-11-22 10:18:29.000000', NULL, 0),
(6229872, 919430, 61315, '<td valign="top">BEAUTIFUL Katie! Great score for a great shot!</td>', 'BEAUTIFUL Katie! Great score for a great shot!', '2010-11-22 10:40:35.000000', NULL, 0),
(6229876, 919168, 86447, '<td valign="top">Eeewww... creepy!   LOL!</td>', 'Eeewww... creepy!   LOL!', '2010-11-22 10:50:49.000000', NULL, 0),
(6229877, 920044, 86447, '<td valign="top">I love the colors... well done on all of it, Carole!</td>', 'I love the colors... well done on all of it, Carole!', '2010-11-22 10:54:50.000000', NULL, 0),
(6229878, 919407, 83313, '<td valign="top">Sub-5!!!!???? Got to be a joke! You got totally robbed!! Should have at least gotten more comments. Well, I suppose that''s the fate of any <a href="//www.dpchallenge.com/image.php?IMAGE_ID=805160" rel="nofollow" target="_blank">Star Trek themed entry</a>. A very narrow (but highly appreciative) audience.<br/> <br/>My vote was the lone 10, BTW. Sorry I couldn''t provide the other 16 you needed.<br/><br/><i>Message edited by author 2010-11-22 11:03:17.</i></td>', 'Sub-5!!!!???? Got to be a joke! You got totally robbed!! Should have at least gotten more comments. Well, I suppose that''s the fate of any Star Trek themed entry. A very narrow (but highly appreciative) audience. My vote was the lone 10, BTW. Sorry I couldn''t provide the other 16 you needed.', '2010-11-22 10:57:09.000000', '2010-11-22 11:03:17.000000', 0),
(6229880, 918871, 61315, '<td valign="top">Well done portrait Lydia - love the lighting, DOF, and the placement of the eyes!</td>', 'Well done portrait Lydia - love the lighting, DOF, and the placement of the eyes!', '2010-11-22 10:58:37.000000', NULL, 0),
(6229881, 919866, 96751, '<td valign="top">I''ve been doing the happy dance all over the place for you.  Congrats for the blue on what is undoubtedly the best of the bunch.</td>', 'I''ve been doing the happy dance all over the place for you.  Congrats for the blue on what is undoubtedly the best of the bunch.', '2010-11-22 11:00:37.000000', NULL, 0),
