(6229895, 920010, 61315, '<td valign="top">Beautiful shot - love it, the reflection, pose, the mist, and of course the off-centered composition! Congrats on your HM!</td>', 'Beautiful shot - love it, the reflection, pose, the mist, and of course the off-centered composition! Congrats on your HM!', '2010-11-22 11:09:44.000000', NULL, 0),
